<details class="panel" open><summary>Batas periode & hari efektif</summary><form method="post"><?=csrf_field()?><?php ak_hidden('action','periode');ak_hidden('id_tahun_ajaran',$periodId);?><div class="form-grid"><?php ak_field('mulai','Mulai',$settings['mulai']??'','date');ak_field('selesai','Selesai',$settings['selesai']??'','date');ak_field('hari_efektif','Hari efektif (1=Senin … 7=Minggu)',$settings['hari_efektif']??'');ak_select('terverifikasi','Keputusan verifikasi',['0'=>'Belum diverifikasi','1'=>'Terverifikasi oleh admin'],$settings['terverifikasi']??0);?></div><?php ak_field('catatan','Dasar verifikasi / catatan',$settings['catatan']??'');?><button type="submit">Simpan aturan periode</button></form></details>
<details class="panel" <?=$member?'open':''?>><summary><?=$member?'Edit / tutup':'Tambah'?> keanggotaan kelas</summary><form method="post"><?=csrf_field()?><?php ak_hidden('action','anggota');ak_hidden('id_tahun_ajaran',$periodId);if($member)ak_hidden('id',$member['id']);?><div class="form-grid"><?php ak_select('nis','Siswa (NIS)',$studentOptions,$member['nis']??'');ak_select('id_kelas','Kelas',$classes,$member['id_kelas']??'');ak_field('nomor_absen','Nomor absen',$member['nomor_absen']??'','number');ak_field('mulai','Berlaku mulai',$member['mulai']??'','date');ak_field('selesai','Berlaku sampai',$member['selesai']??'','date');?></div><?php ak_field('alasan','Alasan pengaturan / penutupan rentang');?><button type="submit">Simpan keanggotaan</button></form></details>
<details class="panel" <?=$window?'open':''?>><summary>Verifikasi rentang penugasan guru</summary><form method="post"><?=csrf_field()?><?php ak_hidden('action','penugasan');$scheduleOptions=[];foreach(ak_rows('SELECT j.*,k.nama_kelas,g.nama_guru,m.nama_mapel FROM jadwal j JOIN kelas k USING(id_kelas) JOIN guru g USING(id_guru) JOIN mata_pelajaran m USING(id_mapel) WHERE j.id_tahun_ajaran=? ORDER BY j.id_jadwal',[$periodId]) as $j)$scheduleOptions[$j['id_jadwal']]='#'.$j['id_jadwal'].' '.$j['nama_guru'].' · '.$j['nama_kelas'].' · '.$j['nama_mapel'].' · '.$j['hari'];?><div class="form-grid"><?php ak_select('id_jadwal','Jadwal',$scheduleOptions,$window['id_jadwal']??'');ak_field('mulai','Berlaku mulai',$window['mulai']??'','date');ak_field('selesai','Berlaku sampai',$window['selesai']??'','date');ak_select('terverifikasi','Keputusan verifikasi',['0'=>'Belum diverifikasi','1'=>'Terverifikasi'],$window['terverifikasi']??0);?></div><?php ak_field('catatan','Dasar verifikasi',$window['catatan']??'');?><button type="submit">Simpan rentang penugasan</button></form></details>
<details class="panel" <?=$duty?'open':''?>><summary>Penugasan Guru Piket & izin koreksi</summary><form method="post"><?=csrf_field()?><?php ak_hidden('action','piket');ak_hidden('id_tahun_ajaran',$periodId);if($duty)ak_hidden('id',$duty['id']);?><div class="form-grid"><?php ak_select('id_guru','Guru',$teachers,$duty['id_guru']??'');ak_select('id_kelas','Cakupan kelas (kosong = seluruh sekolah)',$classes,$duty['id_kelas']??'',false);ak_field('mulai','Berlaku mulai',$duty['mulai']??'','date');ak_field('selesai','Berlaku sampai',$duty['selesai']??'','date');ak_select('boleh_koreksi','Koreksi data terkonfirmasi',['0'=>'Hanya monitor & rekonsiliasi awal','1'=>'Diizinkan, dengan alasan & audit'],$duty['boleh_koreksi']??0);?></div><?php ak_field('catatan','Dasar penugasan / perubahan izin',$duty['catatan']??'');?><button type="submit">Simpan tugas Guru Piket</button><?php if($duty):?><button type="submit" class="secondary" name="operation" value="cabut">Cabut tugas</button><?php endif;?></form></details>
<section class="panel"><h2>Anggota kelas pada periode</h2><div class="table-scroll"><table><thead><tr><th>Kelas</th><th>No.</th><th>NIS</th><th>Nama</th><th>Berlaku</th><th>Aksi</th></tr></thead><tbody><?php foreach(ak_rows('SELECT a.*,s.nama_siswa,k.nama_kelas FROM ak_anggota_kelas a JOIN siswa s ON s.nis=a.nis JOIN kelas k ON k.id_kelas=a.id_kelas WHERE a.id_tahun_ajaran=? ORDER BY k.nama_kelas,a.nomor_absen,a.mulai',[$periodId]) as $row):?><tr><td><?=e($row['nama_kelas'])?></td><td><?=e($row['nomor_absen'])?></td><td><?=e($row['nis'])?></td><td><?=e($row['nama_siswa'])?></td><td><?=e($row['mulai'])?> — <?=e($row['selesai'])?></td><td><a class="button secondary" href="<?=e(ak_link('fondasi',['id_tahun_ajaran'=>$periodId,'anggota'=>$row['id']]))?>">Edit / tutup</a></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="panel"><h2>Tugas Guru Piket</h2><?php foreach(ak_rows('SELECT p.*,g.nama_guru,k.nama_kelas FROM ak_tugas_piket p JOIN guru g USING(id_guru) LEFT JOIN kelas k USING(id_kelas) WHERE p.id_tahun_ajaran=? ORDER BY p.id DESC',[$periodId]) as $row):?><article class="history-entry"><h3><?=e($row['nama_guru'])?> · <?=e($row['nama_kelas']??'Seluruh sekolah')?></h3><p><?=e($row['mulai'])?> — <?=e($row['selesai'])?> · <?=$row['aktif']?'Aktif':'Dicabut'?> · <?=$row['boleh_koreksi']?'Dengan izin koreksi':'Tanpa izin koreksi'?></p><a class="button secondary" href="<?=e(ak_link('fondasi',['id_tahun_ajaran'=>$periodId,'piket'=>$row['id']]))?>">Edit / cabut izin</a></article><?php endforeach;?></section>

